package ru.truetv.launcher;
import android.app.*;
import android.os.*;
import android.widget.*;
import java.util.concurrent.*;
/** Explicit same-device ADB start/stop for the volume helper ported from our TV Mouse1.9. */
final class VolumeTools {
 private final Activity owner;private final SettingsStore prefs;private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean busy;private AlertDialog progress;
 VolumeTools(Activity owner){this.owner=owner;prefs=new SettingsStore(owner);}
 private String w(String ru,String en){return Ui.word(owner,ru,en);}
 private String endpoint(){return prefs.text("access_endpoint",prefs.text("expert_endpoint","127.0.0.1:5555"));}
 void show(){ActionSheet.show(owner,w("Восстановление удержания громкости","Restore volume-key hold"),new ActionSheet.Item(w("Запустить восстановление через ADB","Start restoration through ADB"),"power",()->confirm(true)),new ActionSheet.Item(w("Остановить восстановление","Stop restoration"),"close",()->confirm(false)),new ActionSheet.Item(w("Адрес ADB: ","ADB address: ")+endpoint(),"tune",this::address),new ActionSheet.Item(w("Как работает восстановление","How restoration works"),"info",this::guide));}
 private void guide(){new AlertDialog.Builder(owner).setTitle(w("Удержание громкости","Volume-key hold")).setMessage(w("Если после включения службы лаунчера в специальных возможностях перестало работать удержание кнопок громкости, запустите восстановление.\n\nИспользуется тот же помощник, что в нашем TV Mouse: только громкость, без захвата устройства ввода. Нужны включённый и разрешённый ADB на этом телевизоре. Настройка подключения находится в TV Access. После перезагрузки запуск повторяется вручную. Если помощник уже запущен в TV Mouse, остановите его там перед запуском здесь.\n\nНекоторые прошивки запрещают getevent или инъекцию ввода для ADB. Тогда этот способ недоступен; приложение не меняет системную защиту.","If holding volume keys stops working after enabling the launcher service in Accessibility, start restoration.\n\nThis is the same helper as in our TV Mouse: volume keys only, without grabbing an input device. ADB must be enabled and authorized on this TV. Connection setup is available in TV Access. Start it again manually after a reboot. If the helper is already running in TV Mouse, stop it there first.\n\nSome firmware blocks getevent or input injection for ADB. This method is then unavailable; the app does not change system protection.")).setPositiveButton("OK",null).show();}
 private void address(){EditText input=new EditText(owner);input.setSingleLine();input.setText(endpoint());AlertDialog dialog=new AlertDialog.Builder(owner).setTitle(w("Адрес ADB этого устройства","This device's ADB address")).setView(input).setNegativeButton(w("Отмена","Cancel"),null).setPositiveButton(w("Сохранить","Save"),null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{try{String value=input.getText().toString().trim();AdbWire.endpoint(value);prefs.data.edit().putString("access_endpoint",value).apply();dialog.dismiss();}catch(IllegalArgumentException invalid){input.setError(w("Введите адрес:порт","Enter address:port"));}}));dialog.show();}
 private void confirm(boolean start){if(busy)return;new AlertDialog.Builder(owner).setTitle(w(start?"Запустить восстановление?":"Остановить восстановление?",start?"Start restoration?":"Stop restoration?")).setMessage("ADB · "+endpoint()+"\n\n"+w(start?"Будет запущен помощник только для удержания кнопок громкости. После перезагрузки запустите снова.":"Остановится только помощник громкости True TV Launcher.",start?"Start the volume-key hold helper only. Start it again after a reboot.":"Stop only True TV Launcher's volume helper.")).setNegativeButton(w("Отмена","Cancel"),null).setPositiveButton(w(start?"Запустить":"Остановить",start?"Start":"Stop"),(d,which)->run(start)).show();}
 private void run(boolean start){if(busy)return;busy=true;progress=new AlertDialog.Builder(owner).setTitle(w("Восстановление удержания громкости","Restore volume-key hold")).setMessage(w("При запросе RSA разрешите ADB на этом устройстве.","Approve ADB on this device if an RSA prompt appears.")).setCancelable(false).show();worker.execute(()->{String result;try(ExpertBackend adb=new ExpertBackend(owner,false,endpoint())){String apk=owner.getApplicationInfo().sourceDir;if(start){ShellReply launched=adb.shell(VolumeCommand.start(apk));if(launched.code!=0)throw new java.io.IOException(launched.text);}else{ShellReply stopped=adb.shell(VolumeCommand.stop(apk));if(stopped.code!=0)throw new java.io.IOException(stopped.text);}boolean running=false;for(int i=0;i<8;i++){Thread.sleep(250);ShellReply state=adb.shell(VolumeCommand.status(apk));if(state.code!=0)throw new java.io.IOException(state.text);String value=state.text.trim();if(!value.equals("TRUE_TV_VOLUME_RUNNING")&&!value.equals("TRUE_TV_VOLUME_STOPPED"))throw new java.io.IOException("Volume helper status not confirmed");running=value.equals("TRUE_TV_VOLUME_RUNNING");if(running==start)break;}if(running!=start){ShellReply log=adb.shell("tail -c 2048 "+PackagePolicy.quote(VolumeCommand.BASE+".log"));throw new java.io.IOException(w("Помощник не подтвердил работу: ","Helper state not confirmed: ")+log.text);}result=w(start?"Восстановление запущено. Проверьте удержание громкости. После перезагрузки запустите снова.":"Восстановление остановлено.",start?"Restoration started. Check holding the volume keys. Start it again after a reboot.":"Restoration stopped.");}catch(Exception failure){result=w("Не выполнено: ","Not completed: ")+failure.getMessage();}final String message=result;owner.runOnUiThread(()->{busy=false;if(owner.isFinishing()||owner.isDestroyed())return;if(progress!=null){progress.dismiss();progress=null;}new AlertDialog.Builder(owner).setTitle(w("Удержание громкости","Volume-key hold")).setMessage(message).setPositiveButton("OK",null).show();});});}
 void close(){if(progress!=null){progress.dismiss();progress=null;}worker.shutdown();}
}
